// Verifica il token di autenticazione PRIMA di leggere qualunque dato paziente.
// Il token atteso è una variabile d'ambiente n8n (DASHBOARD_SECRET_TOKEN), mai hardcoded nel workflow.
const received = $input.item.json?.headers?.['x-secretaria-token'] ?? '';
const expected = $env.DASHBOARD_SECRET_TOKEN ?? '';

if (!expected) {
  throw new Error('DASHBOARD_SECRET_TOKEN non configurato lato n8n: rifiuto per sicurezza ogni richiesta finché non viene impostato.');
}

const authorized = received.length > 0 && received === expected;

return {
  json: {
    authorized,
    ...( $input.item.json )
  }
};

// Trasforma le righe del foglio nel formato JSON che la dashboard si aspetta
const rows = $input.all();

const tickets = rows.map((r) => {
  const j = r.json || {};
  return {
    id: j.ID || '',
    timestamp: j.Timestamp || '',
    paziente: j.Paziente || 'N/D',
    telefono: j.Telefono || 'N/D',
    urgenza: (j.Urgenza || 'VERDE').toString().toUpperCase().trim(),
    categoria: j.Categoria || 'Altro',
    richiesta: j.Richiesta || '',
    azione: j.Azione || '',
    status: j.Status || 'APERTO',
    chatId: j.ChatID || ''
  };
}).filter(t => t.id); // scarta righe vuote

// Ordina per timestamp decrescente (i più recenti in cima)
tickets.sort((a, b) => (b.timestamp || '').localeCompare(a.timestamp || ''));

return [{ json: { tickets, count: tickets.length, fetchedAt: new Date().toISOString() } }];
